    icon = "MessageSquareWarning"
    name = "F10TerminalResultMessage"

    inputs = [
        DataInput(
            name="terminal_events",
            display_name="최종 처리 이벤트 (자동 연결)",
            input_types=["Data", "JSON"],
            required=False,
            is_list=True,
            advanced=False,
            info="취소·반려·차단 경로가 하나의 이벤트 목록으로 자동 연결됩니다. 여러 선택 입력을 직접 채우지 않습니다.",
